//! Deterministic artifact generation engine derived from `ferrix.config.toml`.
//!
//! Generates AndroidManifest.xml, resources (strings, themes, splash, network security,
//! locales config), and compile-time metadata without requiring manual edits.

use crate::schema::FerrixConfig;
use std::fs;
use std::path::Path;

pub const GENERATED_FILE_HEADER: &str =
    "<!-- Generated by Ferrix. Single source of truth is ferrix.config.toml. Do not edit manually. -->";

impl FerrixConfig {
    /// Resolves the application name for a given variant (applying `name_suffix` if configured).
    pub fn resolved_app_name(&self, variant: Option<&str>) -> String {
        if let Some(v_name) = variant {
            if let Some(v_cfg) = self.build.variants.get(v_name) {
                if let Some(suffix) = &v_cfg.name_suffix {
                    return format!("{}{}", self.app.name, suffix);
                }
            }
        }
        self.app.name.clone()
    }

    /// Resolves the application ID for a given variant (applying `id_suffix` if configured).
    pub fn resolved_app_id(&self, variant: Option<&str>) -> String {
        if let Some(v_name) = variant {
            if let Some(v_cfg) = self.build.variants.get(v_name) {
                if let Some(suffix) = &v_cfg.id_suffix {
                    return format!("{}{}", self.app.id, suffix);
                }
            }
        }
        self.app.id.clone()
    }

    /// Generates AndroidManifest.xml conforming to Ferrix specifications:
    /// - Decoupled host namespace `dev.ferrix.host.MainActivity`
    /// - Explicit permissions, features, allowBackup, networkSecurityConfig
    /// - Split intent-filters for custom schemes and App Links (autoVerify)
    pub fn generate_android_manifest(&self, _variant: Option<&str>) -> String {
        let mut out = String::new();
        out.push_str("<?xml version=\"1.0\" encoding=\"utf-8\"?>\n");
        out.push_str(GENERATED_FILE_HEADER);
        out.push_str(
            "\n<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\">\n\n",
        );

        // Permissions
        for perm in &self.android.permissions {
            let full_perm = if perm.contains('.') {
                perm.clone()
            } else {
                format!("android.permission.{}", perm)
            };
            out.push_str(&format!(
                "    <uses-permission android:name=\"{}\" />\n",
                full_perm
            ));
        }

        // Features
        for feat in &self.android.features {
            out.push_str(&format!(
                "    <uses-feature android:name=\"{}\" android:required=\"{}\" />\n",
                feat.name, feat.required
            ));
        }

        out.push_str("\n    <application\n");
        out.push_str(&format!(
            "        android:allowBackup=\"{}\"\n",
            self.android.allow_backup
        ));
        out.push_str("        android:label=\"@string/app_name\"\n");
        out.push_str("        android:supportsRtl=\"true\"\n");
        out.push_str("        android:icon=\"@mipmap/ic_launcher\"\n");
        if self.icon.round {
            out.push_str("        android:roundIcon=\"@mipmap/ic_launcher_round\"\n");
        }
        out.push_str("        android:theme=\"@style/Theme.App.Starting\"\n");

        if !self.android.cleartext_domains.is_empty() {
            out.push_str(
                "        android:networkSecurityConfig=\"@xml/network_security_config\"\n",
            );
        }

        if self.locale.supported.len() > 1 {
            out.push_str("        android:localeConfig=\"@xml/locales_config\"\n");
        }

        out.push_str("    >\n");

        // Activity (fixed host namespace)
        out.push_str("        <activity\n");
        out.push_str("            android:name=\"dev.ferrix.host.MainActivity\"\n");
        out.push_str("            android:exported=\"true\"\n");
        if self.app.orientation != "default" && self.app.orientation != "per-screen" {
            let screen_orientation = match self.app.orientation.as_str() {
                "portrait" => "portrait",
                "landscape" => "landscape",
                _ => "unspecified",
            };
            out.push_str(&format!(
                "            android:screenOrientation=\"{}\"\n",
                screen_orientation
            ));
        }
        out.push_str("            android:configChanges=\"orientation|screenSize|screenLayout|keyboardHidden\">\n");

        // Main launcher intent filter
        out.push_str("            <intent-filter>\n");
        out.push_str("                <action android:name=\"android.intent.action.MAIN\" />\n");
        out.push_str(
            "                <category android:name=\"android.intent.category.LAUNCHER\" />\n",
        );
        out.push_str("            </intent-filter>\n");

        // Deep links: custom schemes
        let mut all_schemes = self.deep_links.schemes.clone();
        if let Some(s) = &self.app.scheme {
            if !all_schemes.contains(s) {
                all_schemes.push(s.clone());
            }
        }

        for scheme in all_schemes {
            out.push_str("            <intent-filter>\n");
            out.push_str(
                "                <action android:name=\"android.intent.action.VIEW\" />\n",
            );
            out.push_str(
                "                <category android:name=\"android.intent.category.DEFAULT\" />\n",
            );
            out.push_str(
                "                <category android:name=\"android.intent.category.BROWSABLE\" />\n",
            );
            out.push_str(&format!(
                "                <data android:scheme=\"{}\" />\n",
                scheme
            ));
            out.push_str("            </intent-filter>\n");
        }

        // Deep links: web hosts (App Links)
        for host_cfg in &self.deep_links.hosts {
            let auto_verify_attr = if host_cfg.auto_verify {
                " android:autoVerify=\"true\""
            } else {
                ""
            };
            out.push_str(&format!(
                "            <intent-filter{}>\n",
                auto_verify_attr
            ));
            out.push_str(
                "                <action android:name=\"android.intent.action.VIEW\" />\n",
            );
            out.push_str(
                "                <category android:name=\"android.intent.category.DEFAULT\" />\n",
            );
            out.push_str(
                "                <category android:name=\"android.intent.category.BROWSABLE\" />\n",
            );
            out.push_str("                <data android:scheme=\"https\" />\n");
            out.push_str("                <data android:scheme=\"http\" />\n");
            out.push_str(&format!(
                "                <data android:host=\"{}\" />\n",
                host_cfg.host
            ));

            for path in &host_cfg.paths {
                let (attr_name, val) = path.to_attribute();
                out.push_str(&format!(
                    "                <data {}=\"{}\" />\n",
                    attr_name, val
                ));
            }
            out.push_str("            </intent-filter>\n");
        }

        out.push_str("        </activity>\n");
        out.push_str("    </application>\n");
        out.push_str("</manifest>\n");

        out
    }

    /// Generates res/values/strings.xml
    pub fn generate_strings_xml(&self, variant: Option<&str>) -> String {
        let name = self.resolved_app_name(variant);
        format!(
            r#"<?xml version="1.0" encoding="utf-8"?>
{header}
<resources>
    <string name="app_name">{name}</string>
</resources>
"#,
            header = GENERATED_FILE_HEADER,
            name = escape_xml(&name)
        )
    }

    /// Generates res/values/themes.xml (or res/values-night/themes.xml)
    pub fn generate_themes_xml(&self, dark: bool) -> String {
        let bg = if dark {
            &self.splash.dark_background
        } else {
            &self.splash.background
        };
        format!(
            r#"<?xml version="1.0" encoding="utf-8"?>
{header}
<resources>
    <!-- Base splash theme using Android 12+ SplashScreen API -->
    <style name="Theme.App.Starting" parent="Theme.SplashScreen">
        <item name="windowSplashScreenBackground">{bg}</item>
        <item name="windowSplashScreenAnimatedIcon">@drawable/splash_icon</item>
        <item name="postSplashScreenTheme">@android:style/Theme.Material.Light.NoActionBar</item>
    </style>
</resources>
"#,
            header = GENERATED_FILE_HEADER,
            bg = bg
        )
    }

    /// Generates res/xml/network_security_config.xml
    pub fn generate_network_security_config(&self) -> Option<String> {
        if self.android.cleartext_domains.is_empty() {
            return None;
        }

        let mut domains = String::new();
        for domain in &self.android.cleartext_domains {
            domains.push_str(&format!(
                "        <domain includeSubdomains=\"true\">{}</domain>\n",
                escape_xml(domain)
            ));
        }

        Some(format!(
            r#"<?xml version="1.0" encoding="utf-8"?>
{header}
<network-security-config>
    <domain-config cleartextTrafficPermitted="true">
{domains}    </domain-config>
</network-security-config>
"#,
            header = GENERATED_FILE_HEADER,
            domains = domains
        ))
    }

    /// Generates res/xml/locales_config.xml for Android 13+ per-app languages
    pub fn generate_locales_config(&self) -> String {
        let mut locales = String::new();
        for loc in &self.locale.supported {
            locales.push_str(&format!("    <locale android:name=\"{}\" />\n", loc));
        }

        format!(
            r#"<?xml version="1.0" encoding="utf-8"?>
{header}
<locale-config xmlns:android="http://schemas.android.com/apk/res/android">
{locales}</locale-config>
"#,
            header = GENERATED_FILE_HEADER,
            locales = locales
        )
    }

    /// Generates digital asset links JSON (`.well-known/assetlinks.json`)
    pub fn generate_assetlinks_json(&self, fingerprints: &[&str]) -> String {
        let package_name = &self.app.id;
        let fps: Vec<String> = fingerprints
            .iter()
            .map(|fp| format!("        \"{}\"", fp))
            .collect();

        format!(
            r#"[
  {{
    "relation": ["delegate_permission/common.handle_all_urls"],
    "target": {{
      "namespace": "android_app",
      "package_name": "{pkg}",
      "sha256_cert_fingerprints": [
{fps}
      ]
    }}
  }}
]
"#,
            pkg = package_name,
            fps = fps.join(",\n")
        )
    }

    /// Generates Gradle productFlavors Kotlin DSL block
    pub fn generate_gradle_flavors(&self) -> String {
        if self.build.variants.is_empty() {
            return String::new();
        }

        let mut out = String::new();
        out.push_str("    flavorDimensions.add(\"environment\")\n");
        out.push_str("    productFlavors {\n");

        for (variant_name, cfg) in &self.build.variants {
            out.push_str(&format!("        create(\"{}\") {{\n", variant_name));
            out.push_str("            dimension = \"environment\"\n");
            if let Some(suffix) = &cfg.id_suffix {
                out.push_str(&format!(
                    "            applicationIdSuffix = \"{}\"\n",
                    suffix
                ));
            }
            if let Some(suffix) = &cfg.name_suffix {
                out.push_str(&format!(
                    "            manifestPlaceholders[\"appLabelSuffix\"] = \"{}\"\n",
                    suffix
                ));
            }
            out.push_str("        }\n");
        }

        out.push_str("    }\n");
        out
    }

    /// Generates a typed Rust metadata module (`ferrix_config.rs`) for the app crate.
    pub fn generate_rust_config_mod(&self, variant: Option<&str>) -> String {
        let id = self.resolved_app_id(variant);
        let name = self.resolved_app_name(variant);
        let version = &self.app.version;
        let variant_str = variant.unwrap_or("default");

        format!(
            r#"// Generated by Ferrix. Single source of truth is ferrix.config.toml.
// Do not edit manually.

pub mod app {{
    pub const ID: &str = "{id}";
    pub const NAME: &str = "{name}";
    pub const VERSION: &str = "{version}";
    pub const VARIANT: &str = "{variant_str}";
}}
"#
        )
    }

    /// Writes all generated Android artifacts into the target Android main source directory
    /// (e.g. `android/app/src/main/`).
    pub fn write_all_artifacts(
        &self,
        main_dir: &Path,
        variant: Option<&str>,
    ) -> Result<(), std::io::Error> {
        let res_dir = main_dir.join("res");
        let values_dir = res_dir.join("values");
        let values_night_dir = res_dir.join("values-night");
        let xml_dir = res_dir.join("xml");
        let drawable_dir = res_dir.join("drawable");

        fs::create_dir_all(&values_dir)?;
        fs::create_dir_all(&values_night_dir)?;
        fs::create_dir_all(&xml_dir)?;
        fs::create_dir_all(&drawable_dir)?;

        // 1. AndroidManifest.xml
        fs::write(
            main_dir.join("AndroidManifest.xml"),
            self.generate_android_manifest(variant),
        )?;

        // 2. strings.xml
        fs::write(
            values_dir.join("strings.xml"),
            self.generate_strings_xml(variant),
        )?;

        // 3. themes.xml (light & night)
        fs::write(
            values_dir.join("themes.xml"),
            self.generate_themes_xml(false),
        )?;
        fs::write(
            values_night_dir.join("themes.xml"),
            self.generate_themes_xml(true),
        )?;

        // 4. network_security_config.xml
        if let Some(net_cfg) = self.generate_network_security_config() {
            fs::write(xml_dir.join("network_security_config.xml"), net_cfg)?;
        }

        // 5. locales_config.xml
        if self.locale.supported.len() > 1 {
            fs::write(
                xml_dir.join("locales_config.xml"),
                self.generate_locales_config(),
            )?;
        }

        // 6. Default placeholder splash_icon drawable if not present
        let splash_icon_path = drawable_dir.join("splash_icon.xml");
        if !splash_icon_path.exists() {
            let placeholder_splash = r##"<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="288dp"
    android:height="288dp"
    android:viewportWidth="24"
    android:viewportHeight="24">
    <path
        android:fillColor="#FFFFFF"
        android:pathData="M12,2L2,22h20L12,2z" />
</vector>
"##;
            fs::write(splash_icon_path, placeholder_splash)?;
        }

        // 7. Launcher icons (adaptive layers and colors)
        let mipmap_anydpi_dir = res_dir.join("mipmap-anydpi-v26");
        fs::create_dir_all(&mipmap_anydpi_dir)?;

        let colors_xml = format!(
            r##"<?xml version="1.0" encoding="utf-8"?>
{header}
<resources>
    <color name="ic_launcher_background">{bg}</color>
</resources>
"##,
            header = GENERATED_FILE_HEADER,
            bg = self.icon.adaptive_background
        );
        fs::write(values_dir.join("colors.xml"), colors_xml)?;

        let fg_path = drawable_dir.join("ic_launcher_foreground.xml");
        if !fg_path.exists() {
            let placeholder_fg = r##"<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="108dp"
    android:height="108dp"
    android:viewportWidth="108"
    android:viewportHeight="108">
    <path
        android:fillColor="#FFFFFF"
        android:pathData="M54,34L34,74h40L54,34z" />
</vector>
"##;
            fs::write(fg_path, placeholder_fg)?;
        }

        let adaptive_xml = r##"<?xml version="1.0" encoding="utf-8"?>
<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">
    <background android:drawable="@color/ic_launcher_background" />
    <foreground android:drawable="@drawable/ic_launcher_foreground" />
    <monochrome android:drawable="@drawable/ic_launcher_foreground" />
</adaptive-icon>
"##;
        fs::write(mipmap_anydpi_dir.join("ic_launcher.xml"), adaptive_xml)?;
        fs::write(
            mipmap_anydpi_dir.join("ic_launcher_round.xml"),
            adaptive_xml,
        )?;

        Ok(())
    }
}

fn escape_xml(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&apos;")
}
